"""Generate isolated, editable continuation projects; never edits the original labs."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]/'demo/spring-boot-crash/continuation'
def put(name,text):
    p=ROOT/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text.strip()+'\n',encoding='utf-8')
def java(module,name,text,test=False):
    put(f'{module}/src/{"test" if test else "main"}/java/hub/{module}/{name}.java','package hub.'+module+';\n'+text)
def pom(module,deps,extra=''):
    dependencies=''
    for dep in deps:
        parts=dep.split(':');g,a=parts[:2];v=parts[2] if len(parts)>2 else '';scope=parts[3] if len(parts)>3 else ''
        dependencies+=f'<dependency><groupId>{g}</groupId><artifactId>{a}</artifactId>'+ (f'<version>{v}</version>' if v else '')+(f'<scope>{scope}</scope>' if scope else '')+'</dependency>\n'
    put(module+'/pom.xml',f'''<project xmlns="http://maven.apache.org/POM/4.0.0"><modelVersion>4.0.0</modelVersion>
<parent><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-parent</artifactId><version>3.5.16</version><relativePath/></parent>
<groupId>hub</groupId><artifactId>{module}</artifactId><version>1.0.0</version><properties><java.version>25</java.version></properties>
<dependencies>{dependencies}</dependencies><build><plugins><plugin><groupId>org.springframework.boot</groupId><artifactId>spring-boot-maven-plugin</artifactId></plugin></plugins></build>{extra}</project>''')
starters=lambda *names:['org.springframework.boot:spring-boot-starter-'+n for n in names]
pom('commerce',starters('web','data-jpa','validation','security','actuator','aop','mail','amqp')+['com.h2database:h2','org.postgresql:postgresql','org.flywaydb:flyway-core','org.flywaydb:flyway-database-postgresql','org.springdoc:springdoc-openapi-starter-webmvc-ui:2.8.17','io.github.resilience4j:resilience4j-spring-boot3:2.3.0','io.micrometer:micrometer-registry-prometheus','io.micrometer:micrometer-tracing-bridge-otel','org.springframework.boot:spring-boot-starter-test::test','org.springframework.security:spring-security-test::test','org.testcontainers:postgresql::test','org.testcontainers:junit-jupiter::test'])
