java('commerce','Files',r'''import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.core.io.*;
import org.springframework.http.*;
import org.springframework.web.server.ResponseStatusException;
import java.nio.file.*;
import java.security.Principal;
import java.util.*;
import java.io.IOException;
@RestController @RequestMapping("/api/v1/files")
public class Files {
 private final Path root;private final JdbcTemplate db;
 public Files(@Value("${app.upload-directory}") String directory,JdbcTemplate db)throws IOException {root=Path.of(directory).toAbsolutePath().normalize();java.nio.file.Files.createDirectories(root);this.db=db;}
 @PostMapping public Map<String,String> upload(@RequestParam MultipartFile file,Principal p)throws IOException {if(file.isEmpty()||file.getSize()>1048576)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"File must contain 1–1048576 bytes");byte[] bytes=file.getBytes();if(bytes.length<5||!new String(bytes,0,5,java.nio.charset.StandardCharsets.US_ASCII).equals("%PDF-"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"This example accepts PDF headers only");String id=UUID.randomUUID().toString();java.nio.file.Files.write(root.resolve(id),bytes,StandardOpenOption.CREATE_NEW);db.update("insert into attachment values (?,?,?)",id,p.getName(),"document.pdf");return Map.of("id",id);}
 @GetMapping("/{id}") public ResponseEntity<Resource> download(@PathVariable UUID id,Principal p) {if(db.queryForList("select id from attachment where id=? and owner=?",String.class,id.toString(),p.getName()).isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return ResponseEntity.ok().header("Content-Disposition","attachment; filename=\"document.pdf\"").header("X-Content-Type-Options","nosniff").contentType(MediaType.APPLICATION_PDF).body(new FileSystemResource(root.resolve(id.toString())));}
}''')
java('commerce','PaymentClient',r'''import org.springframework.stereotype.Component;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.client.RestClient;
import org.springframework.http.client.SimpleClientHttpRequestFactory;
import org.springframework.util.LinkedMultiValueMap;
import org.springframework.http.MediaType;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import java.util.Map;
@Component
public class PaymentClient {
 private final RestClient client;private final String key,url;
 public Map<?,?> session(String id) {return client.get().uri("/v1/checkout/sessions/{id}",id).headers(h->h.setBasicAuth(key,"")).retrieve().body(Map.class);}
 public Map<?,?> refundStatus(String id) {return client.get().uri("/v1/refunds/{id}",id).headers(h->h.setBasicAuth(key,"")).retrieve().body(Map.class);}
 public PaymentClient(@Value("${payment.base-url}") String base,@Value("${payment.key}") String key,@Value("${app.public-url}") String url) {var factory=new SimpleClientHttpRequestFactory();factory.setConnectTimeout(2000);factory.setReadTimeout(5000);this.client=RestClient.builder().baseUrl(base).requestFactory(factory).build();this.key=key;this.url=url;}
 public record Checkout(String id,String url) {}
 public Checkout checkout(PurchaseOrder order) {if(!key.startsWith("sk_test_"))throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Set a Stripe test-mode key first");var form=new LinkedMultiValueMap<String,String>();form.add("mode","payment");form.add("success_url",url+"/swagger-ui/index.html");form.add("cancel_url",url+"/swagger-ui/index.html");form.add("client_reference_id",order.id.toString());form.add("metadata[orderId]",order.id.toString());form.add("line_items[0][price_data][currency]","usd");form.add("line_items[0][price_data][product_data][name]",order.product);form.add("line_items[0][price_data][unit_amount]","2500");form.add("line_items[0][quantity]",String.valueOf(order.quantity));Map<?,?> result=client.post().uri("/v1/checkout/sessions").headers(h->h.setBasicAuth(key,"")).header("Idempotency-Key","checkout-"+order.id).contentType(MediaType.APPLICATION_FORM_URLENCODED).body(form).retrieve().body(Map.class);return new Checkout((String)result.get("id"),(String)result.get("url"));}
 public Map<?,?> refund(Long orderId,String intent) {return client.post().uri("/v1/refunds").headers(h->h.setBasicAuth(key,"")).header("Idempotency-Key","refund-"+orderId).contentType(MediaType.APPLICATION_FORM_URLENCODED).body("payment_intent="+intent).retrieve().body(Map.class);}
}''')
java('commerce','PaymentService',r'''import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import java.util.Map;
@Service
public class PaymentService {
 private final Orders orders;private final OrderService ownership;private final PaymentClient client;private final JdbcTemplate db;
 public PaymentService(Orders orders,OrderService ownership,PaymentClient client,JdbcTemplate db) {this.orders=orders;this.ownership=ownership;this.client=client;this.db=db;}
 @Transactional public PaymentClient.Checkout checkout(Long id,String owner) {ownership.owned(id,owner);var order=orders.lock(id).orElseThrow();if(!order.status.equals("PENDING"))throw new ResponseStatusException(HttpStatus.CONFLICT);if(order.checkoutUrl!=null)return new PaymentClient.Checkout(order.checkoutId,order.checkoutUrl);var checkout=client.checkout(order);order.checkoutId=checkout.id();order.checkoutUrl=checkout.url();return checkout;}
 @Transactional public void paid(String eventId,Long id,String session,String intent,long amount,String currency) {var order=orders.lock(id).orElseThrow();if(!db.queryForList("select id from payment_event where id=?",String.class,eventId).isEmpty())return;if(!session.equals(order.checkoutId)||amount!=order.totalCents||!currency.equals("usd"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Payment details do not match order");if(!order.status.equals("PENDING")&&!order.status.equals("PAID"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Reconcile payment for cancelled order");db.update("insert into payment_event values (?)",eventId);order.paymentId=intent;order.status="PAID";}
 @Transactional public PurchaseOrder reconcile(Long id,String owner) {ownership.owned(id,owner);var o=orders.lock(id).orElseThrow();if(o.status.equals("PENDING")&&o.checkoutId!=null){var r=client.session(o.checkoutId);if("paid".equals(r.get("payment_status")))paid("reconcile-"+o.checkoutId,id,o.checkoutId,String.valueOf(r.get("payment_intent")),((Number)r.get("amount_total")).longValue(),String.valueOf(r.get("currency")));}else if(o.status.equals("REFUND_PENDING")){var r=client.refundStatus(o.refundId);if("succeeded".equals(r.get("status")))o.status="REFUNDED";}return o;}
 @Transactional public Map<?,?> refund(Long id,String owner) {ownership.owned(id,owner);var o=orders.lock(id).orElseThrow();if(!o.status.equals("PAID"))throw new ResponseStatusException(HttpStatus.CONFLICT);var result=client.refund(id,o.paymentId);o.refundId=String.valueOf(result.get("id"));o.status="REFUND_PENDING";return result;}
}''')
java('commerce','Payments',r'''import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import com.fasterxml.jackson.databind.ObjectMapper;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.Instant;
import java.util.*;
@RestController
public class Payments {
 private final PaymentService service;private final ObjectMapper json;private final String secret;
 public Payments(PaymentService service,ObjectMapper json,@Value("${payment.webhook-secret}") String secret) {this.service=service;this.json=json;this.secret=secret;}
 @PostMapping("/api/v1/orders/{id}/checkout") public PaymentClient.Checkout checkout(@PathVariable Long id,java.security.Principal p) {return service.checkout(id,p.getName());}
 @PostMapping("/api/v1/orders/{id}/reconcile") public PurchaseOrder reconcile(@PathVariable Long id,java.security.Principal p) {return service.reconcile(id,p.getName());}
 @PostMapping("/api/v1/orders/{id}/refund") public Map<?,?> refund(@PathVariable Long id,java.security.Principal p) {return service.refund(id,p.getName());}
 static boolean valid(String raw,String header,String secret,long now) {try {String timestamp=null;List<String> signatures=new ArrayList<>();for(String part:header.split(",")){String[] pair=part.split("=",2);if(pair[0].equals("t"))timestamp=pair[1];if(pair[0].equals("v1"))signatures.add(pair[1]);}if(timestamp==null||Math.abs(now-Long.parseLong(timestamp))>300||secret.isBlank())return false;Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));byte[] expected=mac.doFinal((timestamp+"."+raw).getBytes(StandardCharsets.UTF_8));for(String signature:signatures)if(MessageDigest.isEqual(expected,HexFormat.of().parseHex(signature)))return true;return false;}catch(Exception e){return false;}}
 @PostMapping("/webhooks/stripe") public void webhook(@RequestBody String raw,@RequestHeader("Stripe-Signature") String signature)throws Exception {if(!valid(raw,signature,secret,Instant.now().getEpochSecond()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid webhook signature");var event=json.readTree(raw);if(event.path("type").asText().equals("checkout.session.completed")){var o=event.path("data").path("object");if(o.path("payment_status").asText().equals("paid"))service.paid(event.path("id").asText(),Long.valueOf(o.path("metadata").path("orderId").asText()),o.path("id").asText(),o.path("payment_intent").asText(),o.path("amount_total").asLong(),o.path("currency").asText());}}
}''')
