java('workflow','NodeSecurity',r'''import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import org.springframework.beans.factory.annotation.Value;
import jakarta.servlet.*;
import jakarta.servlet.http.*;
import java.io.IOException;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
@Component
public class NodeSecurity extends OncePerRequestFilter {
 private final String secret;public NodeSecurity(@Value("${workflow.secret}") String secret){if(secret.length()<16)throw new IllegalArgumentException("Set WORKFLOW_SECRET to at least 16 characters");this.secret=secret;}
 protected void doFilterInternal(HttpServletRequest q,HttpServletResponse r,FilterChain chain)throws ServletException,IOException {if(q.getRequestURI().startsWith("/actuator/health")){chain.doFilter(q,r);return;}String candidate=q.getHeader("X-Workflow-Key");if(candidate==null||!MessageDigest.isEqual(candidate.getBytes(StandardCharsets.UTF_8),secret.getBytes(StandardCharsets.UTF_8))){r.sendError(401);return;}chain.doFilter(q,r);}
}''')
java('workflow','Participant',r'''import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;
@RestController @RequestMapping("/effects")
public class Participant {
 private final JdbcTemplate db;private final String role;
 public Participant(JdbcTemplate db,@Value("${node.role}") String role){this.db=db;this.role=role;}
 public record Command(String id,String action,boolean fail,long expectedVersion) {}
 @PostMapping @Transactional public Map<String,Object> apply(@RequestBody Command c){
  if(!Set.of("inventory","payment").contains(role))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Run a participant role");
  String key=role+":"+c.id();var existing=db.queryForList("select * from effect where id=? for update",key);
  String target=switch(c.action()){case "reserve"->"RESERVED";case "commit"->"COMMITTED";case "release"->"RELEASED";case "charge"->"CHARGED";case "refund"->"REFUNDED";default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST);};
  if(role.equals("inventory")&&!Set.of("reserve","commit","release").contains(c.action())||role.equals("payment")&&!Set.of("charge","refund").contains(c.action()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);
  if(existing.isEmpty()) {if(!Set.of("reserve","charge").contains(c.action()))throw new ResponseStatusException(HttpStatus.CONFLICT);db.update("insert into effect values (?,?,0,?)",key,c.fail()?"DECLINED":target,System.currentTimeMillis()+60000);}
  else {String state=(String)existing.getFirst().get("STATE");long version=((Number)existing.getFirst().get("VERSION")).longValue();if(state.equals(target))return Map.of("state",state,"version",version);if(state.equals("DECLINED"))return Map.of("state",state,"version",version);if(c.expectedVersion()>=0&&version!=c.expectedVersion())throw new ResponseStatusException(HttpStatus.CONFLICT,"Stale version");if(!(state.equals("RESERVED")&&Set.of("commit","release").contains(c.action())||state.equals("CHARGED")&&c.action().equals("refund")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Illegal or stale transition");db.update("update effect set state=?,version=version+1 where id=?",target,key);}
  return db.queryForMap("select state,version from effect where id=?",key);
 }
 @GetMapping("/{id}") public List<Map<String,Object>> status(@PathVariable String id){return db.queryForList("select * from effect where id=?",role+":"+id);}
}''')
java('workflow','WorkflowStore',r'''import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
@Service
public class WorkflowStore {
 private final JdbcTemplate db;public WorkflowStore(JdbcTemplate db){this.db=db;}
 @Transactional public String create(String id,boolean failPayment,boolean failConfirm,String correlation){if(db.queryForList("select id from workflow where id=?",String.class,id).isEmpty()){db.update("insert into workflow values (?,'NEW',0,0,?,?,?)",id,failPayment,failConfirm,correlation);event(id,"OrderCreated",correlation);}return id;}
 public void event(String id,String kind,String correlation){db.update("insert into outbox values (?,?,?,false,?)",UUID.randomUUID().toString(),id,kind,correlation);}
 @Transactional public void transition(String id,String expected,String next,String correlation){if(db.update("update workflow set phase=?,attempts=0,next_attempt=0 where id=? and phase=?",next,id,expected)==1)event(id,next,correlation);}
 public Map<String,Object> get(String id){return db.queryForMap("select * from workflow where id=?",id);}
}''')
java('workflow','Orchestrator',r'''import org.springframework.stereotype.Service;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.client.RestClient;
import org.springframework.http.client.SimpleClientHttpRequestFactory;
import org.slf4j.*;
import java.util.*;
@Service
public class Orchestrator {
 private final JdbcTemplate db;private final WorkflowStore store;private final RestClient http;private final String inventory,payment,role,mode;private final Logger log=LoggerFactory.getLogger(getClass());
 public Orchestrator(JdbcTemplate db,WorkflowStore store,@Value("${inventory.url}") String inventory,@Value("${payment.url}") String payment,@Value("${node.role}") String role,@Value("${workflow.mode}") String mode,@Value("${workflow.secret}") String secret){this.db=db;this.store=store;this.inventory=inventory;this.payment=payment;this.role=role;this.mode=mode;var f=new SimpleClientHttpRequestFactory();f.setConnectTimeout(500);f.setReadTimeout(1000);http=RestClient.builder().requestFactory(f).defaultHeader("X-Workflow-Key",secret).build();}
 public String effect(String url,String id,String action,boolean fail,String correlation){Map<?,?> result=http.post().uri(url+"/effects").header("X-Correlation-ID",correlation).body(new Participant.Command(id,action,fail,-1)).retrieve().body(Map.class);Object value=result.containsKey("STATE")?result.get("STATE"):result.get("state");return String.valueOf(value);}
 @Scheduled(fixedDelay=500) public void tick(){if(!role.equals("order")||!mode.equals("orchestration"))return;for(var row:db.queryForList("select * from workflow where phase not in ('COMPLETED','CANCELLED','MANUAL_REVIEW') and next_attempt<=?",System.currentTimeMillis()))advance(row);}
 public void advance(Map<String,Object> row){String id=(String)row.get("ID"),phase=(String)row.get("PHASE"),correlation=(String)row.get("CORRELATION");String next=phase;try{switch(phase){case "NEW"->{effect(inventory,id,"reserve",false,correlation);next="RESERVED";}case "RESERVED"->{String state=effect(payment,id,"charge",(Boolean)row.get("FAIL_PAYMENT"),correlation);next=state.equals("DECLINED")?"RELEASING":"CHARGED";}case "CHARGED"->{if((Boolean)row.get("FAIL_CONFIRM"))next="REFUNDING";else{effect(inventory,id,"commit",false,correlation);next="COMPLETED";}}case "REFUNDING"->{effect(payment,id,"refund",false,correlation);next="RELEASING";}case "RELEASING"->{effect(inventory,id,"release",false,correlation);next="CANCELLED";}default->throw new IllegalStateException(phase);}store.transition(id,phase,next,correlation);log.info("correlation={} order={} {} -> {}",correlation,id,phase,next);}catch(Exception failure){int attempts=((Number)row.get("ATTEMPTS")).intValue()+1;long delay=Math.min(30000,500L*(1L<<Math.min(attempts,6)));db.update("update workflow set attempts=?,next_attempt=?,phase=? where id=? and phase=?",attempts,System.currentTimeMillis()+delay,attempts>=5?"MANUAL_REVIEW":phase,id,phase);log.warn("correlation={} order={} phase={} attempt={} outcome=unknown",correlation,id,phase,attempts);}}
}''')
java('workflow','WorkflowController',r'''import org.springframework.web.bind.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import java.util.*;
@RestController @RequestMapping("/workflows")
public class WorkflowController {
 private final WorkflowStore store;private final JdbcTemplate db;private final String role;
 public WorkflowController(WorkflowStore store,JdbcTemplate db,@Value("${node.role}") String role){this.store=store;this.db=db;this.role=role;}
 public record Start(String id,boolean failPayment,boolean failConfirm) {}
 @PostMapping public Map<String,Object> start(@RequestBody Start r,@RequestHeader(value="X-Correlation-ID",required=false) String correlation){if(!role.equals("order"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);String id=UUID.fromString(r.id()).toString();store.create(id,r.failPayment(),r.failConfirm(),correlation==null?UUID.randomUUID().toString():correlation);return store.get(id);}
 @GetMapping("/{id}") public Map<String,Object> status(@PathVariable String id){return store.get(id);}
 @GetMapping("/{id}/events") public List<Map<String,Object>> events(@PathVariable String id){return db.queryForList("select * from outbox where order_id=?",id);}
}''')
java('workflow','WorkflowTest',r'''import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
@SpringBootTest(properties={"workflow.secret=test-only-long-secret","spring.datasource.url=jdbc:h2:mem:workflow;DB_CLOSE_DELAY=-1","node.role=inventory"})
class WorkflowTest {
 @Autowired Participant participant;@Autowired JdbcTemplate db;
 @BeforeEach void clean(){db.update("delete from effect");}
 @Test void duplicateReserveDoesNotCreateAnotherEffect(){for(int i=0;i<2;i++)participant.apply(new Participant.Command("a","reserve",false,-1));assertEquals(1,db.queryForObject("select count(*) from effect",Integer.class));}
 @Test void staleCommandCannotReverseRelease(){participant.apply(new Participant.Command("a","reserve",false,-1));participant.apply(new Participant.Command("a","release",false,-1));assertThrows(Exception.class,()->participant.apply(new Participant.Command("a","reserve",false,-1)));}
 @Test void versionRejectsConcurrentChange(){participant.apply(new Participant.Command("a","reserve",false,-1));assertThrows(Exception.class,()->participant.apply(new Participant.Command("a","commit",false,2)));}
}''',True)
