java('temporal','CheckoutWorkflowImpl',r'''import io.temporal.workflow.Workflow;
import io.temporal.activity.ActivityOptions;
import io.temporal.common.RetryOptions;
import java.time.Duration;
public class CheckoutWorkflowImpl implements CheckoutWorkflow {
 private final CheckoutActivities activities=Workflow.newActivityStub(CheckoutActivities.class,ActivityOptions.newBuilder().setStartToCloseTimeout(Duration.ofSeconds(5)).setRetryOptions(RetryOptions.newBuilder().setMaximumAttempts(5).build()).build());
 public String checkout(String id,boolean decline) {activities.reserve(id);String result=activities.charge(id,decline);if(result.equals("DECLINED")){activities.release(id);return "CANCELLED";}activities.commit(id);return "COMPLETED";}
}''')
java('temporal','ParticipantActivities',r'''import org.springframework.web.client.RestClient;
import java.util.Map;
public class ParticipantActivities implements CheckoutActivities {
 private final RestClient client;private final String inventory,payment;
 public ParticipantActivities(String secret,String inventory,String payment){client=RestClient.builder().defaultHeader("X-Workflow-Key",secret).build();this.inventory=inventory;this.payment=payment;}
 private String call(String base,String id,String action,boolean fail){Map<?,?> r=client.post().uri(base+"/effects").body(Map.of("id",id,"action",action,"fail",fail,"expectedVersion",-1)).retrieve().body(Map.class);return String.valueOf(r.containsKey("STATE")?r.get("STATE"):r.get("state"));}
 public void reserve(String id){call(inventory,id,"reserve",false);}
 public String charge(String id,boolean decline){return call(payment,id,"charge",decline);}
 public void release(String id){call(inventory,id,"release",false);}
 public void commit(String id){call(inventory,id,"commit",false);}
}''')
java('temporal','WorkerMain',r'''import io.temporal.serviceclient.WorkflowServiceStubs;
import io.temporal.client.WorkflowClient;
import io.temporal.worker.WorkerFactory;
public class WorkerMain {
 public static void main(String[] args){String secret=System.getenv("WORKFLOW_SECRET");if(secret==null||secret.length()<16)throw new IllegalArgumentException("Set WORKFLOW_SECRET first");var service=WorkflowServiceStubs.newLocalServiceStubs();var client=WorkflowClient.newInstance(service);var factory=WorkerFactory.newInstance(client);var worker=factory.newWorker("checkout");worker.registerWorkflowImplementationTypes(CheckoutWorkflowImpl.class);worker.registerActivitiesImplementations(new ParticipantActivities(secret,"http://localhost:8101","http://localhost:8102"));factory.start();}
}''')
java('temporal','ClientMain',r'''import io.temporal.serviceclient.WorkflowServiceStubs;
import io.temporal.client.*;
public class ClientMain {
 public static void main(String[] args){if(args.length!=1)throw new IllegalArgumentException("Supply a fresh workflow UUID");var service=WorkflowServiceStubs.newLocalServiceStubs();try{var client=WorkflowClient.newInstance(service);var flow=client.newWorkflowStub(CheckoutWorkflow.class,WorkflowOptions.newBuilder().setTaskQueue("checkout").setWorkflowId("checkout-"+args[0]).build());System.out.println(flow.checkout(args[0],false));}finally{service.shutdown();}}
}''')
